/**
 * Layout centers all the elements for displaying the
 * error and its metadata
 */
#layout {
  max-width: 1280px;
  margin: auto;
  display: flex;
  flex-direction: column;
  gap: 24px;
  padding: calc(1vw + 15px);
}

.card {
  background: var(--card-bg);
  box-shadow: var(--card-shadow);
  border-radius: var(--radius);
  padding: calc(2vw + 7px);
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.card-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.card-title {
  font-size: 18px;
  color: var(--title-fg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.card-subtitle {
  color: var(--subtitle-fg);
  font-size: 12px;
  font-weight: 600;
  margin-top: 20px;
  margin-bottom: 10px;
  text-transform: uppercase;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.card-table {
  width: 100%;
  max-width: 100%;
  border-spacing: 0;
  table-layout: fixed;
  overflow: scroll;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.card-table td {
  border-bottom: 1px solid var(--border);
  padding: calc(0.8vw + 4px) calc(0.8vw + 8px);
  word-wrap: break-word;
}

.card-table tr:last-child td {
  border-bottom: 0;
}

.card-table td.table-value .dumper-dump pre {
  padding: 0;
  -webkit-font-smoothing: initial;
  -moz-osx-font-smoothing: initial;
}

@media (min-width: 768px) {
  #layout {
    padding: 40px;
  }

  .card {
    padding: 22px 30px;
  }

  .card-table td {
    padding: 6px 12px;
  }

  .card-table td.table-key {
    width: 180px;
  }

  .dumper-dump pre {
    padding: 10px 15px;
  }
}

